    }

    It 'groups secrets into Expired, Warning, and Ok buckets' {
        $report.Expired.Count | Should -Be 2
        $report.Warning.Count | Should -Be 3
        $report.Ok.Count | Should -Be 1
    }

    It 'puts the correct secrets in the Expired bucket' {
